lxml.html.__init__.open_http_urllib:
def open_http_urllib(method, url, values):
    if not url:
        raise ValueError('cannot submit, no URL provided')
    try:
        from urllib import urlencode, urlopen
    except ImportError:
        from urllib.request import urlopen
        from urllib.parse import urlencode
    if method == 'GET':
        if '?' in url:
            url += '&'
        else:
            url += '?'
        url += urlencode(values)
        data = None
    else:
        data = urlencode(values)
        if not isinstance(data, bytes):
            data = data.encode('ASCII')
    return urlopen(url, data)

lxml.ElementInclude._wrap_et_loader:
def _wrap_et_loader(loader):

    def load(href, parse, encoding=None, parser=None):
        return loader(href, parse, encoding)
    return load

lxml.html.soupparser.unescape:
def unescape(string):
    if not string:
        return ''

    def unescape_entity(m):
        try:
            return unichr(name2codepoint[m.group(1)])
        except KeyError:
            return m.group(0)
    return handle_entities(unescape_entity, string)

lxml.html.diff._fixup_ins_del_tags:
def _fixup_ins_del_tags(doc):
    """fixup_ins_del_tags that works on an lxml document in-place
    """
    for tag in ['ins', 'del']:
        for el in doc.xpath('descendant-or-self::%s' % tag):
            if not _contains_block_level_tag(el):
                continue
            _move_el_inside_block(el, tag=tag)
            el.drop_tag()

lxml.html.formfill._find_elements_for_na:
def _find_elements_for_name(form, name, error):
    if name is None:
        yield (form, error)
        return
    if name.startswith('#'):
        el = form.get_element_by_id(name[1:])
        if el is not None:
            yield (el, error)
        return
    els = _name_xpath(form, name=name)
    if not els:
        return
    if not isinstance(error, (list, tuple)):
        yield (els[0], error)
        return
    for (el, err) in zip(els, error):
        if err is None:
            continue
        yield (el, err)
